package dev.nla;
import dev.nla.warehouse.*;import org.springframework.stereotype.Service;import java.nio.file.*;import java.sql.*;import java.time.*;import java.util.*;
@Service public class PipelineService {
 private final Store store;private final Adapters adapters;private final SqlGuard guard;private final CatalogService catalog;
 public PipelineService(Store s,Adapters a,SqlGuard g,CatalogService c){store=s;adapters=a;guard=g;catalog=c;}
 public List<Map<String,Object>> configurations(){List<Map<String,Object>> configs=new ArrayList<>();for(String suffix:List.of("pg","mysql","mssql")){Path p=Path.of(System.getProperty("nla.data.root","../data"),"chinook","pipeline-"+suffix+".json");if(Files.exists(p))try{var conf=Json.read(Files.readString(p));store.authorize(Json.str(conf,"warehouseId"));store.warehouse(Json.str(conf,"warehouseId"));configs.add(conf);}catch(ApiException ignored){}catch(java.io.IOException e){throw new IllegalStateException("Registered pipeline unreadable");}}return configs;}
 public List<Map<String,Object>> sources(){return configurations().stream().map(c->Json.obj("sourceId",c.get("sourceId"),"name",c.get("name"),"type",c.get("type"),"status","ACTIVE","warehouseId",c.get("warehouseId"),"datasetId",c.get("datasetId"))).toList();}
 public synchronized Map<String,Object> run(Map<String,Object>b){RegistryController.fields(b,Set.of("warehouseId","datasetId","sourceId","idempotencyKey"));RegistryController.required(b,"warehouseId","datasetId","sourceId","idempotencyKey");String key=Json.str(b,"idempotencyKey");if(key.length()>100)throw ApiException.bad("Idempotency key quá dài.");String signature=Json.str(b,"warehouseId")+"/"+Json.str(b,"datasetId")+"/"+Json.str(b,"sourceId");var existing=store.jdbc().query("SELECT signature,run_id FROM ingestion_request WHERE actor=? AND request_key=?",(rs,n)->Map.of("signature",rs.getString(1),"runId",rs.getString(2)),store.actor(),key);if(!existing.isEmpty()){if(!existing.getFirst().get("signature").equals(signature))throw new ApiException(org.springframework.http.HttpStatus.CONFLICT,"INVALID_REQUEST","Idempotency key đã dùng với payload khác.");return store.run(existing.getFirst().get("runId"),"INGESTION");}
  var cfg=configurations().stream().filter(c->Json.str(c,"sourceId").equals(b.get("sourceId"))&&Json.str(c,"warehouseId").equals(b.get("warehouseId"))&&Json.str(c,"datasetId").equals(b.get("datasetId"))).findFirst().orElseThrow(ApiException::notFound);var w=store.warehouse(Json.str(b,"warehouseId"));var d=store.dataset(Json.str(b,"datasetId"));if(!"ACTIVE".equals(w.get("status"))||!"ACTIVE".equals(d.get("status")))throw new ApiException(org.springframework.http.HttpStatus.CONFLICT,"DATASET_UNAVAILABLE","Warehouse/dataset không hoạt động.");String id=Json.id("ing");var steps=new ArrayList<Map<String,Object>>();for(String stage:List.of("RAW","STAGING","WAREHOUSE","MART"))steps.add(Json.obj("stage",stage,"status","PENDING","durationMs",null,"error",null));var run=Json.obj("runId",id,"batchId",Json.id("batch"),"warehouseId",w.get("warehouseId"),"datasetId",d.get("datasetId"),"engine",w.get("engine"),"status","RUNNING","sourceId",cfg.get("sourceId"),"rowsWritten",0,"rejectedCount",0,"startedAt",Instant.now().toString(),"completedAt",null,"durationMs",null,"idempotent",true,"steps",steps,"error",null);store.run(id,"INGESTION",run);store.jdbc().update("INSERT INTO ingestion_request(actor,request_key,signature,run_id) VALUES (?,?,?,?)",store.actor(),key,signature,id);long start=System.nanoTime();int active=0;
  try{var adapter=adapters.get(w);var validated=guard.validate(Json.str(cfg,"readSql"),Json.str(w,"engine"),catalog.tables(Json.str(d,"datasetId")));var raw=adapter.executeReadOnlyQuery(w,adapters.password(store.credential(Json.str(w,"warehouseId"))),validated.sql(),1000,5242880,15);if(Boolean.TRUE.equals(raw.get("truncated")))throw ApiException.bad("Nguồn pipeline vượt giới hạn đã cấu hình.");done(steps.get(active++),start);var rows=Json.objects(raw.get("rows"));long rejected=rows.stream().filter(row->row.get("country")==null||row.get("total")==null||Objects.toString(row.get("country"),"").length()>100).count();run.put("rejectedCount",rejected);if(rejected>0)throw ApiException.bad("Dữ liệu nguồn không vượt qua kiểm tra chất lượng; không ghi mart.");var writer=new LinkedHashMap<>(w);writer.put("username","nla_writer");try(Connection conn=adapter.connect(writer,adapters.password(Json.str(cfg,"credentialReference")))){conn.setAutoCommit(false);try{String stage=qualified(adapter,Json.map(cfg.get("stage"))),mart=qualified(adapter,Json.map(cfg.get("mart")));try(Statement stmt=conn.createStatement()){adapter.configureTimeout(stmt,15);stmt.executeUpdate("DELETE FROM "+stage);}try(PreparedStatement stmt=conn.prepareStatement("INSERT INTO "+stage+" (country,total) VALUES (?,?)")){adapter.configureTimeout(stmt,15);for(var row:rows){stmt.setString(1,row.get("country").toString());stmt.setBigDecimal(2,new java.math.BigDecimal(row.get("total").toString()));stmt.addBatch();}stmt.executeBatch();}done(steps.get(active++),start);try(Statement stmt=conn.createStatement()){adapter.configureTimeout(stmt,15);stmt.executeUpdate("DELETE FROM "+mart);stmt.executeUpdate("INSERT INTO "+mart+" (country,total) SELECT country,total FROM "+stage);}done(steps.get(active++),start);try(Statement stmt=conn.createStatement();ResultSet check=stmt.executeQuery("SELECT COUNT(*) FROM "+mart)){check.next();if(check.getInt(1)!=rows.size())throw new SQLException("Mart integrity mismatch");}conn.commit();done(steps.get(active++),start);run.put("rowsWritten",rows.size());run.put("status","SUCCESS");}catch(Exception e){conn.rollback();throw e;}}}
  catch(Exception e){org.slf4j.LoggerFactory.getLogger(PipelineService.class).warn("Pipeline failure engine={} phase={} exception={} code={}",w.get("engine"),active,e.getClass().getSimpleName(),e instanceof SQLException sql?sql.getSQLState():e instanceof ApiException api?api.code:"UNKNOWN");run.put("status","FAILED");var error=Errors.body("INGESTION_ERROR","Pipeline thất bại; writer transaction được rollback, không thay dữ liệu Chinook nguồn.",Json.obj());run.put("error",error);if(active<steps.size()){steps.get(active).put("status","FAILED");steps.get(active).put("error",error);}for(int i=active+1;i<steps.size();i++)steps.get(i).put("status","SKIPPED");}
  run.put("durationMs",(System.nanoTime()-start)/1000000);run.put("completedAt",Instant.now().toString());store.run(id,"INGESTION",run);store.audit("INGESTION_"+run.get("status"),id);return run;
 }
 private static void done(Map<String,Object> step,long start){step.put("status","SUCCESS");step.put("durationMs",(System.nanoTime()-start)/1000000);}
 private static String qualified(WarehouseAdapter adapter,Map<String,Object>t){return adapter.quoteIdentifier(Json.str(t,"schema"))+"."+adapter.quoteIdentifier(Json.str(t,"name"));}
}
